def content_children(greed, sizes):
    greed = sorted(greed)
    sizes = sorted(sizes)
    i = 0
    j = 0
    while i < len(greed) and j < len(sizes):
        if sizes[j] >= greed[i]:
            i += 1
        j += 1
    return i


def main():
