def lemonade_change(bills):
    fives = 0
    tens = 0
    for b in bills:
        if b == 5:
            fives += 1
        elif b == 10:
            if fives == 0:
                return False
            fives -= 1
            tens += 1
        else:
            if tens > 0 and fives > 0:
                tens -= 1
                fives -= 1
            elif fives >= 3:
                fives -= 3
            else:
                return False
    return True


def main():
    bills = list(map(int, input().split()))
    print(lemonade_change(bills))


main()

def max_tickets(costs, budget):
    spent = 0
    count = 0
    for c in sorted(costs):
        if spent + c <= budget:
            spent += c
            count += 1
        else:
            break
    return count


def main():
    costs = list(map(int, input().split()))
    budget = int(input())
    print(max_tickets(costs, budget))


main()

def last_stone(stones):
    pile = sorted(stones)
    while len(pile) > 1:
        y = pile.pop()
        x = pile.pop()
        if y > x:
            d = y - x
            i = len(pile)
            while i > 0 and pile[i - 1] > d:
                i -= 1
            pile.insert(i, d)
    if pile:
        return pile[0]
    return 0


def main():
    stones = list(map(int, input().split()))
    print(last_stone(stones))


main()

