def can_cross(jumps):
    reach = 0
    for i in range(len(jumps)):
        if i > reach:
            break
        if i + jumps[i] > reach:
            reach = i + jumps[i]
    return reach >= len(jumps) - 1


def main():
    jumps = list(map(int, input().split()))
    print(can_cross(jumps))


