def max_pairs(socks, k):
    socks = sorted(socks)
    pairs = 0
    i = 0
    while i < len(socks) - 1:
        if socks[i + 1] - socks[i] <= k:
            pairs += 1
            i += 2
        else:
            i += 1
    return pairs


