def fractional_knapsack(weights, values, W):
    order = sorted(range(len(weights)), key=lambda i: values[i] / weights[i], reverse=True)
    total = 0.0
    cap = W
    for i in order:
        if cap <= 0:
            break
        if weights[i] <= cap:
            total += values[i]
            cap -= weights[i]
        else:
            total += values[i] * cap / weights[i]
            cap = 0
    return total


def main():
    weights = list(map(int, input().split()))
    values = list(map(int, input().split()))
    W = int(input())
    print('{:.2f}'.format(fractional_knapsack(weights, values, W)))


main()

