def max_profit(jobs):
    order = sorted(jobs, key=lambda j: j[1], reverse=True)
    slots = []
    for _ in range(55):
        slots.append(False)
    total = 0
    for d, p in order:
        t = d
        while t >= 1 and slots[t]:
            t -= 1
        if t >= 1:
            slots[t] = True
            total += p
    return total


def main():
    n = int(input())
    jobs = read_pairs(n)
    print(max_profit(jobs))


